// ./src/AboutUs.js
import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import Footer from './components/Footer';
import ISText from './assets/IronpulseText.png';
import HeroImage from './assets/AboutUsHero.jpg';
import TeamImage from './assets/OurTeam.jpg';
import ValuesImage from './assets/OurValues.jpg';
import LegacyImage from './assets/Legacy.jpg';

export default function AboutUs() {
  const sections = [
    {
      title: "Our Team",
      image: TeamImage,
      content: [
        "We began with a single developer in 2023 — learning, experimenting, and building prototypes without funding or industry connections. Passion and creativity drove everything forward.",
        "Like-minded friends soon joined — a small team of dreamers, developers, and storytellers. Together, we founded Iron Shift to make games with passion and purpose."
      ],
    },
    {
      title: "Our Values",
      image: ValuesImage,
      content: [
        "Unyielding Passion & Creativity: The kind that keeps you up at night and drives you just a little crazy — in the best way possible.",
        "Uniquely Driven Development: Fueled by purpose and curiosity — the spark that makes you wake up each day ready to build something new.",
        "Collaboration & Community: Whether introvert or extrovert, there’s a place here. We grow stronger together.",
        "Relentless Innovation: Determined, bold, and maybe a bit stubborn — we push boundaries until they break."
      ],
    },
    {
      title: "The Legacy",
      image: LegacyImage,
      content: [
        "We aim to prove that passion outlives budget. The experiences we create leave lasting impressions and inspire new ambitions.",
        "We refuse to chase trends or compete with industry giants. It’s all about the craft and the feeling we fell in love with as gamers.",
        "Anyone can make a game, but only the passionate can be great."
      ],
    },
  ];

  const fadeInLeft = { hidden: { opacity: 0, x: -50 }, visible: { opacity: 1, x: 0 } };
  const fadeInRight = { hidden: { opacity: 0, x: 50 }, visible: { opacity: 1, x: 0 } };

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 antialiased font-sans flex flex-col">

      {/* HEADER */}
      <header className="w-full fixed z-50 top-0 left-0 px-6 py-6 flex items-center justify-between bg-gradient-to-b from-black to-transparent">
        <img src={ISText} alt="Logo" className="w-36" />
        <Link to="/" className="px-4 py-2 text-sm font-bold text-blue-400 hover:text-white">
          Back Home
        </Link>
      </header>

      {/* HERO */}
      <section
        className="pt-28 relative w-full bg-cover bg-center"
        style={{
          backgroundImage: `url(${HeroImage})`,
          minHeight: '60vh',
        }}
      >
        <div className="absolute inset-0 bg-black/70 z-0" />
        <div className="relative z-10 max-w-4xl mx-auto px-6 text-center py-20">
          <motion.h1
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1 }}
            className="text-4xl md:text-5xl font-bold mb-4"
          >
            About Iron Shift
          </motion.h1>
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3, duration: 1 }}
            className="text-gray-300 text-lg"
          >
            Independent game studio based in South Africa, fueled by passion, creativity, and the drive to make unique experiences.
          </motion.p>
        </div>
      </section>

      {/* MAIN CONTENT */}
      <main className="max-w-7xl mx-auto px-6 space-y-32">

        {sections.map((sec, idx) => {
          const isLeft = idx % 2 === 0;
          return (
            <motion.section
              key={idx}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true, amount: 0.3 }}
              className="relative w-full h-auto lg:h-96 rounded-xl overflow-hidden flex flex-col lg:flex-row items-center"
            >
              {/* IMAGE */}
              <motion.div
                variants={isLeft ? fadeInLeft : fadeInRight}
                className="relative w-full lg:w-1/2 h-64 lg:h-full overflow-hidden rounded-xl"
              >
                <motion.img
                  src={sec.image}
                  alt={sec.title}
                  className="absolute inset-0 w-full h-full object-cover -translate-x-8 lg:-translate-x-16 hover:scale-105 transition-transform duration-500"
                />
                <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-black/0 rounded-xl" />
              </motion.div>

              {/* TEXT */}
              <motion.div
                variants={isLeft ? fadeInRight : fadeInLeft}
                className="relative w-full lg:w-1/2 px-6 py-12 text-gray-100 z-10 space-y-4"
              >
                <h2 className="text-3xl font-bold mb-4">{sec.title}</h2>
                {sec.content.map((c, i) => (
                  <motion.p
                    key={i}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.2 }}
                    className="text-lg"
                  >
                    {c}
                  </motion.p>
                ))}
              </motion.div>
            </motion.section>
          )
        })}

      </main>

      {/* FOOTER */}
      <Footer />
    </div>
  );
}
